-- persons
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('lv-shang', '尚', ARRAY['姜子牙','姜太公','太公'], '姜', '吕', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主','军事家','政治家'], '姜姓，吕氏，名尚，号太公望，通称姜子牙。辅佐周文王、武王，参与克商，前1046年受封于齐营丘；因当地风俗修政，发展工商与鱼盐之利。卒年有异说，一说约前1026年卒，其子吕伋继为齐丁公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姜子牙"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"《资治通鉴外纪》成王条（太公卒年异说）","url":"https://www.shidianguji.com/book/SBCK033/chapter/SBCK033_14"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]'::jsonb, '太公', NULL, '齐太公')
