VALUES ('qi-r12', '禄甫', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐釐公（禄甫），庄公之子，前730–前698年在位。伐纪、伐鲁，齐国国势渐强，为襄公霸业奠基。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐釐公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '釐公', NULL, '齐釐公')
