VALUES ('qi-r13', '诸儿', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐襄公（诸儿），僖公之子，前697–前686年在位。与文姜乱伦，荒于政事，终为连称、管至父弑杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐襄公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·庄公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/莊公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]'::jsonb, '襄公', NULL, '齐襄公')
