VALUES ('qi-r14', '无知', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '公孙无知，齐庄公之孙、釐公之弟夷仲年之子。前686年襄公被弑后获立，次年前685年春为雍廪所杀；齐国一度无君，公子小白随后入齐即位为桓公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/公孙无知"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·庄公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/莊公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]'::jsonb, NULL, NULL, '公孙无知')
