VALUES ('jiang-xiaobai', '小白', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐桓公（小白），僖公之子，前685–前643年在位。任用管仲改革，尊王攘夷，九合诸侯，为春秋五霸之首。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐桓公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]'::jsonb, '桓公', NULL, '齐桓公')
