VALUES ('qi-r16', '无诡', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '公子无亏，又称无诡，齐桓公之子。前643年桓公卒后由易牙、竖刁拥立，孝公昭奔宋；前642年春为齐人所杀，随后宋襄公助昭返国即位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/公子无亏"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]'::jsonb, NULL, NULL, '公子无亏')
