VALUES ('qi-r17', '昭', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐孝公（昭），桓公之子，郑姬所生，前642–前633年在位。宋襄公会诸侯护送回国即位，霸业已衰。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐孝公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]'::jsonb, '孝公', NULL, '齐孝公')
