VALUES ('qi-r18', '潘', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐昭公（潘），桓公之子，葛嬴所生，前632–前613年在位。杀孝公之子夺位，曾随晋文公城濮伐楚。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐昭公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·文公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/文公"}]'::jsonb, '昭公', NULL, '齐昭公')
