VALUES ('qi-r19', '舍', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐君舍，齐昭公与子叔姬之子。前613年父卒后即位，当年为其叔父公子商人所杀，商人自立为齐懿公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/舍_(齊國)"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·文公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/文公"}]'::jsonb, NULL, NULL, '君舍')
