VALUES ('qi-r20', '商人', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐懿公（商人），桓公之子，前612–前609年在位。骄横好杀，因夺邴氏田邑之怨，为邴歜刺杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐懿公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·文公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/文公"}]'::jsonb, '懿公', NULL, '齐懿公')
