VALUES ('qi-r21', '元', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐惠公（元），桓公之子，少卫姬所生，前608–前599年在位。曾避国内乱出奔卫国，后回国即位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐惠公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '惠公', NULL, '齐惠公')
