VALUES ('qi-r22', '无野', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐顷公（无野），惠公之子，前598–前582年在位。戏晋使引发鞍之战，后又与晋议和修好。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐顷公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '顷公', NULL, '齐顷公')
