VALUES ('qi-r23', '环', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐灵公，名环，顷公之子，前581—前554年在位。晏婴父子相继辅政，晚年欲废太子光而立公子牙；病重时崔杼迎回光，灵公卒后光继位为庄公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐灵公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '灵公', NULL, '齐灵公')
