VALUES ('qi-r24', '光', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐庄公，名光，灵公之子，前553—前548年在位。支持栾盈返晋争权，又与崔杼之妻私通，后为崔杼所弑，景公继位，齐国卿族争权加剧。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齊莊公_(光)"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '庄公', NULL, '齐庄公')
