VALUES ('qi-r25', '杵臼', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐景公，名杵臼，庄公异母弟，前547—前490年在位。晏婴曾辅政；晚年立幼子荼为嗣，卒后国惠子、高昭子奉荼继位，随后发生田乞拥立阳生的政变。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐景公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·哀公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/哀公"}]'::jsonb, '景公', NULL, '齐景公')
