VALUES ('qi-r26', '荼', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '安孺子，名荼，齐景公幼子。前490年景公卒后由国惠子、高昭子奉立，前489年田乞政变后被废杀，阳生继位为悼公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安孺子"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·哀公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/哀公"}]'::jsonb, NULL, NULL, '安孺子')
