VALUES ('qi-r27', '阳生', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐悼公（阳生），景公之子，前488–前485年在位。田乞所立，杀芮子诛大夫，后被弑，田氏专权日甚。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐悼公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·哀公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/哀公"}]'::jsonb, '悼公', NULL, '齐悼公')
