VALUES ('qi-r28', '壬', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐简公（壬），悼公之子，前484–前481年在位。任用田常与阚止为相，阚止被杀，简公亦遇害。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐简公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '简公', NULL, '齐简公')
