VALUES ('qi-r29', '骜', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐平公（骜），简公之弟，前480–前456年在位。田成子杀简公而立之，田氏为太宰，君主沦为傀儡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐平公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '平公', NULL, '齐平公')
