VALUES ('qi-r30', '积', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐宣公（积），平公之子，前455–前405年在位。田氏把持国政，前453年韩赵魏灭智氏，春秋步入尾声。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐宣公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '宣公', NULL, '齐宣公')
