VALUES ('jiang-dai', '贷', ARRAY[]::text[], '姜', '齐', NULL, NULL, NULL, NULL, -379, 1, NULL, 'year', ARRAY['君主'], '齐康公（姜贷），姜齐末代。前404年继宣公；前391年田和放逐于海上，姜齐在齐君位止。前379年卒，姜太公之祀绝。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐康公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]'::jsonb, '康公', NULL, '齐康公')
