VALUES ('tian-he', '和', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, -384, 1, NULL, 'year', ARRAY['君主'], '田齐太公（田和）。前391年放逐齐康公自立，前386年周安王列为诸侯，史称田氏代齐。前384年卒。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田和"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, '太公', NULL, '齐太公')
