VALUES ('qi-r33', '剡', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '田侯剡，田和之子，田齐第二代君主，前383—前375年在位。后被其弟田午所杀，田午继位为桓公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田侯剡"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, NULL, NULL, '剡')
