VALUES ('qi-r34', '午', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '田齐桓公，名午，田和之子、田侯剡之弟。杀剡夺位，前374—前357年为在位年表所列年次；卒后其子因齐继位为威王。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田午"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, '桓公', NULL, '齐桓公')
