VALUES ('qi-r35', '因齐', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐威王（因齐），桓公之子，前356–前320年在位。任用邹忌、田忌，悬赏纳谏，齐国大治称强。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐威王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, '威王', NULL, '齐威王')
