VALUES ('qi-r36', '辟彊', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐宣王（辟彊），威王之子，前319–前301年在位。招贤延士，稷下学宫兴盛，促成合纵攻秦。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐宣王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, '宣王', NULL, '齐宣王')
