VALUES ('qi-r37', '地', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐湣王（地），宣王之子，前300–前284年在位。灭宋扩土，后为燕将乐毅联合五国攻破临淄，逃亡被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐湣王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, '湣王', NULL, '齐湣王')
