VALUES ('qi-r38', '法章', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐襄王（法章），湣王庶子匿民间，前283–前265年在位。田单收复临淄，齐国复国但国力大衰。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐襄王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, '襄王', NULL, '齐襄王')
