VALUES ('qi-r39', '建', ARRAY[]::text[], '妫', '田', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '齐王建（建），襄王之子，前264–前221年在位。战国末代齐君，不修战备，秦将王贲攻齐，投降而亡国。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齊王建"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]'::jsonb, NULL, NULL, '建')
