VALUES ('sun-bin', '孙膑', ARRAY[]::text[], NULL, NULL, -378, 1, NULL, 'year', -316, 1, NULL, 'year', ARRAY['军事家'], '战国齐国军事家，曾遭庞涓陷害而受膑刑，后在齐国任军师。协助田忌于桂陵、马陵击败魏军；《史记》称其为孙武后裔，但世系缺乏独立证据，具体身世仍有争议。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙膑"}]'::jsonb, NULL, NULL, NULL)
